/* Original playable projects created with Three.js and Blender. */
(() => {
const card=g=>`<article class="project-card playlab-card"><a href="${g.url}"><img src="${g.image}" alt="${g.title}: cartoon concept cover" loading="lazy"><span class="playlab-badge">PLAYABLE PROTOTYPE ↗</span></a><div class="project-copy"><span>${g.category}</span><h3>${g.title}</h3><p>${g.line}</p>${g.tech?`<small class="playlab-tech">${g.tech}</small>`:''}<div class="playlab-links"><a href="${g.url}">Play now →</a><a href="${g.url}?build=1">How it was made ↗</a></div></div></article>`;
views.playlab={title:'the play lab',status:'6 playable projects · Three.js × Blender',keywords:'play games threejs blender nova duel boost circuit voxel trails rift arena anime football sandbox platformer',render:()=>`<p class="kicker">THE PLAY LAB / SIX PLAYABLE EXPERIENCES</p><h2>Made to be<br><em>played with.</em></h2><p class="intro">Six small browser games exploring combat, physics, creative building and a little handmade adventure. Each has its own controls and build notes. Voxel Trails adapts the supplied Minecraft Web Client, with upstream credits included.</p><div class="project-grid">${window.PlayLab.map(card).join('')}</div><p class="source-note">These are browser game prototypes. Covers are cartoon concept artwork, not gameplay screenshots. The in-game build panels explain the implementation and include editable Blender scenes and GLB exports.</p>`};
const workRender=views.work.render;views.work.render=()=>workRender()+`<section class="playlab-work-section"><p class="kicker">BEYOND THE WEB / ORIGINAL GAME PROJECTS</p><h3>Six worlds to play in.</h3><div class="project-grid">${window.PlayLab.map(card).join('')}</div></section>`;
document.querySelector('.finder-sidebar [data-open="games"]').insertAdjacentHTML('afterend','<button data-open="playlab">◈ <span>Playable lab</span></button>');
})();
